"""Post-processing of the MPVI plan: the keyword cross-check and the tags (design plan 8, D4 addendum 1).

    tagged = postprocess(plan, stop_on_disagreement=False)         # plan: the planner's reply in the schema of src/mpvi_schemas.Plan

Pipeline: planner (the hand-written plan now, the LLM's one call otherwise) -> postprocess() -> tagged plan -> orchestrator. The plan stays plain data (JSON), so it can be logged, cached by
instruction and replayed.

The planner's reply carries, on every manipulation segment, its `primitive` (pick, place or other) and its `objects` (phrases with roles manipulated or destination); both are null on navigation
segments (src/mpvi_schemas.Plan, validated here). There is no separate labeling call any more (David, 2026-10-23, M168). A reply that does not fit the schema, a manipulation segment
without its primitive or objects, or a navigation segment that has them raises PostprocessError: the plan stops before it starts.

What this module adds as plain code (not the LLM): the `check` tag and the `group` number by the paper's rule (the last manipulation step before a navigation step, and the last step of the
plan; consecutive manipulation segments form one unit whose completion criterion is the last step's), and the keyword cross-check.

Keyword cross-check of the primitive: whole words anywhere in the description, case-insensitive: pick up / pick-up / pick / grasp / grab mean pick; place / put / set down mean place. If
the description has both a pick word and a place word the LAST match wins (it matches the end-state completion criterion, so the check triggers on the right gripper event), the segment is
tagged `ambiguous: True` and the case is logged; no match is logged (so verbs can be added once real wordings are seen). The LLM's answer is the one used; the keywords only log. A
disagreement (both gave a pick or place answer, the answers differ, or the LLM says "other" where keywords found a primitive) is logged, and with stop_on_disagreement=True (a setting, off
by default) it raises PostprocessError.

Tagged plan: {"task_name", "segments": [segment + {"index", "check", ("group", "ambiguous", "keyword_primitive" for manipulation segments)}], "postprocess": {"log": [...]}}; the primitive and
the objects are the plan's own fields. The input is not changed.

Contents:
    PostprocessError, keyword_primitive, postprocess.
"""

import re

from pydantic import ValidationError

from src.mpvi_schemas import Plan

PRIMITIVE_WORDS = {"pick": ("pick up", "pick-up", "pick", "grasp", "grab"), "place": ("place", "put", "set down")}
_WORD_RE = re.compile(r"\b(" + "|".join(sorted((w.replace(" ", r"\s+") for ws in PRIMITIVE_WORDS.values() for w in ws), key=len, reverse=True)) + r")\b", re.IGNORECASE)
_WORD_TO_PRIMITIVE = {re.sub(r"\s+", " ", w): p for p, ws in PRIMITIVE_WORDS.items() for w in ws}


class PostprocessError(ValueError):
    """The plan or the labeling reply is not usable; the plan must not start."""


def keyword_primitive(description):
    """Finds the primitive by keywords in a description.

    Args:
        description (str): A manipulation segment's description.

    Returns:
        dict: {"primitive": "pick", "place" or None (no keyword found), "ambiguous": bool (both a pick and a place word found), "matches": list of the words found in order}.
        The last match decides the primitive.
    """
    matches = [re.sub(r"\s+", " ", m.group(1).lower()) for m in _WORD_RE.finditer(description)]
    prims = [_WORD_TO_PRIMITIVE[w] for w in matches]
    return {"primitive": prims[-1] if prims else None, "ambiguous": len(set(prims)) > 1, "matches": matches}


def postprocess(plan, stop_on_disagreement=False, say=print):
    """Tags a plan for the orchestrator.

    Args:
        plan (dict): The planner's reply (src/mpvi_schemas.Plan: the paper's fields plus primitive and objects on the manipulation segments).
        stop_on_disagreement (bool): Raise PostprocessError when the LLM's primitive and the keyword rule disagree. Defaults to False.
        say (callable): Where log lines go (one string each). Defaults to print.

    Returns:
        dict: The tagged plan (see the module docstring); its "postprocess"["log"] lists the logged cases as dicts with "kind" ("no_keyword_match", "ambiguous", "disagreement"), "segment"
        and "description".

    Raises:
        PostprocessError: If the plan does not fit its schema (including a manipulation segment without its primitive or objects, or a navigation segment with them) or (with the setting) the
        answers disagree.
    """
    try:
        valid = Plan.model_validate(plan)
    except ValidationError as e:
        raise PostprocessError(f"the plan does not fit the schema: {e}") from e
    segs = [s.model_dump(mode="json") for s in valid.segments]
    log, tagged, group = [], [], -1

    def note(kind, i, text, **extra):
        log.append({"kind": kind, "segment": i, "description": segs[i]["description"], **extra})
        say(f"[postprocess] {kind} in segment {i} ({segs[i]['description']!r}): {text}")

    for i, s in enumerate(segs):
        t = {**s, "index": i, "check": False}
        if s["type"] == "manipulation":
            prim = s["primitive"]
            kw = keyword_primitive(s["description"])
            if kw["primitive"] is None:
                note("no_keyword_match", i, f"no pick or place word found; the planner says {prim}")
            if kw["ambiguous"]:
                note("ambiguous", i, f"words {kw['matches']}: the last decides, keywords say {kw['primitive']}; the planner says {prim}")
            if kw["primitive"] is not None and prim != kw["primitive"]:
                note("disagreement", i, f"the planner says {prim}, the keywords say {kw['primitive']}", llm=prim, keywords=kw["primitive"])
                if stop_on_disagreement:
                    raise PostprocessError(f"segment {i} ({s['description']!r}): the planner says {prim}, the keywords say {kw['primitive']}")
            if i == 0 or segs[i - 1]["type"] != "manipulation":
                group += 1
            t.update(group=group, ambiguous=kw["ambiguous"], keyword_primitive=kw["primitive"], check=i == len(segs) - 1 or segs[i + 1]["type"] != "manipulation")
        tagged.append(t)
    return {"task_name": valid.task_name, "segments": tagged, "postprocess": {"log": log}}
